$details=@{
C19=@{purpose='Safely select and verify the intended child or parent context before checking restrictions and activating the scoped session.';fields=@('Active child avatar/name/lock status','Distinct Parent Profile tile','Add Child tile','Configured PIN/pattern/OS biometric input','Retry counter only after attempts','Ask a grown-up recovery','Lockout countdown');layout=@('Use friendly large avatar grid only on picker; formal focused PIN gate for parent','Clear old child UI before next context appears','Hide unavailable OS biometric; always preserve durable PIN fallback');states=@('Zero children: parent and Add Child only','Incorrect lock with progressive countdown; input disabled during cooldown','Offline cached lock/signed policy','Biometric unavailable/enrollment changed → PIN','Recovery canceled → original lock unchanged','Restriction denied → specific reason/parent override')};
C20=@{purpose='Give a verified parent a single-child-at-a-time overview with trustworthy freshness and shortcuts to every parent module.';fields=@('Child selector','Milestones/course/lesson/Quran/story/quiz/habit/streak summaries','Badges','Weekly/monthly report previews','Screen-time and bedtime status','AI reasons and safe history link','Plan capacity','As-of timestamp');layout=@('Stack independent cards beneath horizontally scrollable child selector','Text-equivalent trend summary and chart, no sibling ranking','Keep module shortcuts visually distinct from read-only report metrics');states=@('Each card loading/error independently','Report delayed → last passing report plus as-of','Archived child read-only','No activity yet','Offline cached/staleness','Premium insight locked → parent subscription')};
C21=@{purpose='Manage child profiles while retaining disabled data, enforcing capacity and clearly warning before irreversible deletion.';fields=@('Child avatar/name/age/status','Add Child','Edit/Enable/Disable/Delete/Reorder','Nickname','DOB (immutable after first save)','Avatar','Language/level','Interest chips','Daily-goal slider','AI permission');layout=@('Single-column child cards with accessible overflow actions','Disabled cards desaturated with explicit status and historical report access','Deletion uses sober single-focus warning; equal cancel/delete prominence','Provide up/down reorder alternative to dragging');states=@('Zero children','Offline read-only list','Duplicate nickname inline','Capacity block → subscription','Expired step-up on save → fresh gate','Concurrent edits → fresh fetch','Deleting last child allowed with informational note','Downgrade choose N active profiles; 24-hour most-recent fallback')};
C22=@{purpose='Explain learning trends for a selected child and safely connect to deeper skill, AI-safety, report and usage-control views.';fields=@('Global date range','Weekly trend','Habit calendar','Six-state mastery grid','AI safety-event link','Freshness timestamp','Export PDF','Share via WhatsApp','Weekly/monthly/AI insight/safety report content');layout=@('Single scroll column; global filter controls all sections','Use textual chart equivalent and individually labeled mastery tiles','AI safety events use plain chronological list; no transcript bubbles','Monthly view aggregate-only; never side-by-side sibling performance');states=@('Independent loading/delayed/no-activity slices','Not-started skill detail','Clean safety report','Premium report locked/expired at serve-time','Offline cached with export/share blocked','Share canceled at parent gate','PDF generating → system save/share')};
C23=@{purpose='Give verified parents per-child healthy usage, AI, content eligibility and lock/session controls within the platform safety ceiling.';fields=@('Daily learning budget','Usage summary','Quiet hours/bedtime time range','AI on/off','Voice restriction','Language limits','Curated only','Content age band','Per-child lock none/pattern/PIN/biometric','Active devices/Revoke');layout=@('Use consistent grouped setting rows and explicit selected child context','Keep family controls distinct from notification quiet hours','Explain curated-only mode inline','Calm rest screen has one parent-help action; no billing upsell');states=@('Mutations require fresh gate','Offline last signed policy only within grace; no unlimited use','Near-limit warning','Finish short activity/save at time limit','Bedtime pause at natural boundary never mid-Quran-word','Override audited then resume initiating activity','Revoked device force logout')};
C24=@{purpose='Present transparent parent-only subscription choices and store-managed billing with server-verified entitlement.';fields=@('Free Family Starter $0 / 1 active child','Mobile Family $3/mo or $30/yr / 4 children','Premium Family $5.99/mo or $59/yr / 8 children','7-day trial','Post-trial price','Renewal date','Auto-renew disclosure','Current included entitlements','Invoice history','Manage platform subscription','Restore purchase');layout=@('Vertical comparable plan cards; consistently aligned price cadence and capacity','Never use custom payment fields','Keep all trial disclosure rows above purchase CTA','Date/status/freshness explain cached entitlements and pending reconciliation');states=@('Free/Trial/ActivePaid/RenewalPending/PastDue/Canceled/DowngradeScheduled','Canceled retains access until period end','Store cancellation/failure/retry','Delayed webhook signed-grace then reconcile','No invoices yet','Restore success/nothing to restore','Offline cached purchase/upgrade/cancel unavailable','Downgrade routes to C21 child selector')};
C25=@{purpose='Provide parent-scoped notifications, delivery preferences and governed support with reliable ticket submission/status follow-up.';fields=@('Inbox All/System/Safety/Marketing filter','Read/unread/timestamp','Safety-critical channel selector always on','Marketing toggle','Parent quiet hours','FAQ search/results/article','Category billing/technical/content/safety/account-deletion-cancellation/general','Ticket subject/details/status/history/follow-up');layout=@('Conventional inbox and search-first support hub','Safety categories use channel selector rather than toggle','Ticket status stage Submitted → In Progress → Resolved','Explicit Support-only deletion-cancellation entry; no direct cancel-deletion button');states=@('Inbox cached/staleness with mark-read queue','No notifications/no tickets','FAQ no results → contact support','Ticket submit failure preserves draft','Offline FAQ/submission unavailable','Recategorized ticket reflects current category/SLA','Deletion deadline passes before Support action → accurate resolved outcome')};
C26=@{purpose='Give parents granular consent, safe AI-history, account security, language and asynchronous family data-rights controls.';fields=@('Security PIN reset/devices','Consent name/status/date/required-optional','Full governed consent text','Redacted AI input/output summaries','model_version/policy_result/expires_at','Child/date filters','Family default language','Export request/status/download','Delete account entry','Logout');layout=@('Formal settings lists and plain non-chat history','Required consent info-only; optional withdrawal step-up','Export Requested → Preparing → Ready stage indicator','Show family-default versus child override language scope','No celebratory XP effects on privacy/security/delete surfaces');states=@('Cached offline reads; mutations require connectivity','AI always off versus no interactions this period separate','Required consent withdrawal → deletion explanation','Optional regrant appends consent record','Duplicate export reuses/queues existing job','Export failure retry','Revoke device invalidates future auth','Logout unsynced downloads confirmation')}
}
$result=@()
foreach($r in $d.records){
if($r.source_type -match 'Component|variant|System|web'){continue}
if($r.name -match 'Step 1: Step-Up|Parent Override Gate|Share Report — Parent Gate|PIN Reset|Privacy & Support — Data Export Status|Trial-Cancellation/Downgrade Child Selector'){continue}
$feat=$d.features|Where-Object feature -eq $r.feature
$detail=$details[$r.feature]
$map=$maps[$r.name];$site=$null;$fig=$null;$images=@()
if($map){if($map[0]){$site=$s.screens|Where-Object name -eq $map[0]|Select-Object -First 1};if($map[1]){$fig=$f.screens|Where-Object id -eq $map[1]|Select-Object -First 1};if($map[2]){$images=@(Get-ChildItem 'Screens/Mobile App' -Recurse -File|Where-Object{$_.BaseName.StartsWith($map[2])}|ForEach-Object{$_.FullName.Substring((Get-Location).Path.Length+1).Replace('\','/')})}}
$variants=@($d.records|Where-Object{$_.feature -eq $r.feature -and $_.source_type -match 'variant|Component'}|ForEach-Object{@{name=$_.name;entry=$_.entry;exit=$_.destinations;classification=$_.source_type}})
$result+=@{feature=$r.feature;name=$r.name;type=if($r.source_type -match 'Modal'){'overlay'}else{'screen'};purpose=$detail.purpose+' Screen-specific role: '+$r.name+'.';prd=$r.prd;section=$r.section;entry=$r.entry;destinations=$r.destinations;required_fields=$detail.fields;exact_site_copy=if($site){$site.text}else{''};site_reference=if($site){$site.name}else{'Missing in inspected site catalogue'};site_elements=if($site){$site.elements}else{@()};frame1=if($fig){@{id=$fig.id;name=$fig.name;url=('https://www.figma.com/design/MR9935oQZACMjndzGIUgq5/NoorHeroes-APP?node-id='+$fig.id.Replace(':','-'));texts=$fig.texts}}else{$null};frame2=$null;frame2_status='No independently verified equivalent for this screen; global style inspiration must not replace approved copy';source_screen_paths=$images;states=$detail.states;layout_improvements=$detail.layout;inline_components_and_variants=$variants;functional_requirements=$feat.functional_requirements;selected_prd_ux_text=($feat.mobile_sections.Substring($feat.mobile_sections.IndexOf('## 2. UX/UI Requirements')));edge_case_source=($feat.mobile_sections.Substring($feat.mobile_sections.IndexOf('### 1.10'),$feat.mobile_sections.IndexOf('### 1.16')-$feat.mobile_sections.IndexOf('### 1.10')));action_rules='Use screen-specific entry/destinations above and §2.3 click-target table retained in selected_prd_ux_text. Cancel/back returns to invoking parent screen, preserving selected child/date unless original current flow explicitly differs; latter is proposed pending reconciliation.';states_relevance='Feature states are the candidate set; apply only states relevant to this named screen; inline inventory components retain original owning surface';conflicts=@($d.conflicts|Where-Object{$_ -match $r.feature});execution_status=if($site -or $fig){'Reference available; unresolved conflicts require approval before design'}else{'Requirement-driven missing reference; exact labels/content need approval before execution'}}
}
# Required privacy security screen not independently inventoried as a landing surface: proposal must remain explicit.
$result+=@{feature='C26';name='Security (PIN and Device Management landing)';type='screen';purpose='Expose PRD C26 FR1 security settings if existing Settings uses a distinct Security destination; otherwise implement as Settings section.';prd='PRD_Documents/Parent Area In-App (19-26)/Feature_C26_Privacy_Consent_Account_Security_Data_Rights.md';section='§1.7 FR1/FR2/FR11';required_fields=@('PIN/biometric reset entry','Device list entry');execution_status='Proposed independent surface; approve split only if current navigation demonstrates destination';conflicts=@('No independently identified Figma/site screen; do not invent an extra navigation step.')}
$result | ConvertTo-Json -Depth 15 | Set-Content 'sdocs/NoorHeroes_Figma_Enhancement/Research/parent-enriched.json' -Encoding utf8
Write-Output ('Enriched independent screens/overlays='+$result.Count+'; site-mapped='+@($result|Where-Object exact_site_copy).Count+'; Frame1-mapped='+@($result|Where-Object frame1).Count)
